SELECT nextval('TRIALS.SEQ_PERSONAS_ID'), 0, 'Carlos', 'Capturista de Atención a Publico', '', '', 1, 'capturistaap@capturistaap.dev', '', '', '1992-10-10', EC.PN_ID, '', E.PN_ID, 0, 'cacf013c-6fde-441a-a896-2249e6d6a73e', 3, 2
